from dataclasses import dataclass


@dataclass(frozen=True, order=True)
class Point:
    x: int
    y: int


visits = [Point(2, 1), Point(0, 3), Point(2, 1), Point(0, -1), Point(0, 3)]
for p in sorted(visits):
    print(p)
unique = set(visits)
print("Unique:", len(unique))
print(sorted(unique))
counts = {}
for p in visits:
    counts[p] = counts.get(p, 0) + 1
for p, n in counts.items():
    print(f"({p.x}, {p.y}) visited {n}x")

